agent-tree-cancel.source:
/**
 * Agent tree cancellation sample.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 *
 * Demonstrates parent-scope cancellation across multiple in-flight tool tasks.
 * Each task receives the same typed cancellation reason and runs cleanup.
 */

import assert from "node:assert/strict";
import { CancellationError, run } from "../dist/index.js";

const cancelled = [];
const cleanups = [];

await run.scope(async (scope) => {
  const tools = ["search", "browser", "code"];
  const handles = tools.map((name) => scope.spawn(async (ctx) => {
    ctx.defer(() => cleanups.push(name));
    try {
      await sleep(1_000, ctx.signal);
      return name;
    } catch (err) {
      if (err instanceof CancellationError) {
        cancelled.push({ name, reason: err.reason });
      }
      throw err;
    }
  }, { name: `tool.${name}`, kind: "tool" }));

  await sleep(5, scope.signal);
  scope.cancel({ kind: "manual", tag: "user_stopped_agent" });
  await Promise.allSettled(handles);
}, { name: "agent.tree" });

assert.deepEqual(cancelled.map((item) => item.name).sort(), ["browser", "code", "search"]);
assert.deepEqual(cleanups.sort(), ["browser", "code", "search"]);
assert.ok(cancelled.every((item) => item.reason.tag === "user_stopped_agent"));

process.stdout.write(`${JSON.stringify({
  sample: "agent-tree-cancel",
  cancelled: cancelled.map((item) => item.name).sort(),
  reason: cancelled[0]?.reason,
  cleanups: cleanups.sort(),
})}\n`);

function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, ms);
    signal.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(signal.reason);
    }, { once: true });
  });
}

conversation-agent.source:
/**
 * Conversation agent sample.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 *
 * Runs a chat turn with streaming, tool calls, memory write, and cleanup under
 * one WorkIt scope.
 */

import assert from "node:assert/strict";
import { run } from "../dist/index.js";

const tokens = [];
const cleanups = [];
let memoryWrites = 0;

const toolResults = await run.scope(async (scope) => {
  const stream = scope.spawn(async (ctx) => {
    ctx.defer(() => cleanups.push("stream"));
    for (const token of ["plan", "search", "edit", "reply"]) {
      await sleep(1, ctx.signal);
      tokens.push(token);
    }
    return tokens.length;
  }, { name: "llm.stream", kind: "llm" });

  const search = scope.spawn(async (ctx) => {
    ctx.defer(() => cleanups.push("tools"));
    await sleep(2, ctx.signal);
    return "search:2";
  }, { name: "tool.search", kind: "tool" });

  const repo = scope.spawn(async (ctx) => {
    await sleep(3, ctx.signal);
    return "repo:clean";
  }, { name: "tool.repo", kind: "tool" });

  const memory = scope.spawn(async (ctx) => {
    ctx.defer(() => cleanups.push("memory"));
    await sleep(4, ctx.signal);
    memoryWrites++;
    return memoryWrites;
  }, { name: "memory.write", kind: "io" });

  const results = await Promise.all([search, repo]);
  await Promise.all([stream, memory]);
  return results;
}, { name: "chat.turn" });

assert.deepEqual(tokens, ["plan", "search", "edit", "reply"]);
assert.deepEqual(toolResults, ["search:2", "repo:clean"]);
assert.equal(memoryWrites, 1);
assert.deepEqual(cleanups.sort(), ["memory", "stream", "tools"]);

process.stdout.write(`${JSON.stringify({
  sample: "conversation-agent",
  tokens,
  toolResults,
  memoryWrites,
  cleanups: cleanups.sort(),
})}\n`);

function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, ms);
    signal.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(signal.reason);
    }, { once: true });
  });
}

race-providers.source:
/**
 * Provider race sample.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 *
 * Races three provider calls and cancels the losing requests through the shared
 * task signal.
 */

import assert from "node:assert/strict";
import { CancellationError, run } from "../dist/index.js";

const cancelledProviders = [];

const winner = await run.race([
  provider("openai", 50),
  provider("anthropic", 10),
  provider("gemini", 80),
]);

assert.equal(winner.provider, "anthropic");
assert.deepEqual(cancelledProviders.sort(), ["gemini", "openai"]);

process.stdout.write(`${JSON.stringify({
  sample: "race-providers",
  winner: winner.provider,
  cancelledProviders: cancelledProviders.sort(),
})}\n`);

function provider(name, latencyMs) {
  return async (ctx) => {
    try {
      await sleep(latencyMs, ctx.signal);
      return { provider: name, text: `${name}:ok` };
    } catch (err) {
      if (err instanceof CancellationError) cancelledProviders.push(name);
      throw err;
    }
  };
}

function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, ms);
    signal.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(signal.reason);
    }, { once: true });
  });
}

budget-rag.source:
/**
 * Budget-capped RAG sample.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 *
 * Composes rewrite, embedding, source race, hedged reranking, synthesis, and
 * audit background work under one cost budget.
 */

import assert from "node:assert/strict";
import { ContextBagImpl, CostBudget, group, run } from "../dist/index.js";

const budget = { spent: 0, limit: 10, unit: "USD" };
const context = new ContextBagImpl().with(CostBudget, budget);
const audits = [];

const answer = await group(async (task) => {
  const [rewritten, queryVector] = await run.all([
    async (ctx) => {
      ctx.consumeCost(1);
      return "structured concurrency";
    },
    async (ctx) => {
      ctx.consumeCost(2);
      return [0.1, 0.2, 0.3];
    },
  ]);

  const sources = await run.race([
    async (ctx) => {
      await sleep(2, ctx.signal);
      return [`vector:${queryVector.length}`, `keyword:${rewritten}`];
    },
    async (ctx) => {
      await sleep(40, ctx.signal);
      return ["graph:late"];
    },
  ]);

  const reranked = await task(run.hedge(async (ctx) => {
    ctx.consumeCost(2);
    return sources.slice().reverse();
  }, { after: "5ms", max: 2 }), { name: "rag.rerank", kind: "llm" });

  task.background(async () => {
    audits.push({ rewritten, sources: reranked.length });
  });

  return await task(async (ctx) => {
    ctx.consumeCost(3);
    return `answer:${reranked[0]}`;
  }, { name: "rag.synthesize", kind: "llm" });
}, {
  name: "rag.query",
  context,
});
const finalBudget = context.get(CostBudget);

assert.equal(answer, "answer:keyword:structured concurrency");
assert.equal(finalBudget.spent, 8);
assert.deepEqual(audits, [{ rewritten: "structured concurrency", sources: 2 }]);

process.stdout.write(`${JSON.stringify({
  sample: "budget-rag",
  answer,
  spent: finalBudget.spent,
  limit: finalBudget.limit,
  audits,
})}\n`);

function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, ms);
    signal.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(signal.reason);
    }, { once: true });
  });
}
